#!/usr/bin/env node
// scripts/verify-build-output.cjs
// Asserts that the post-build artifacts actually carry the transforms they should.
//
// Run after `napi build --pipe "node scripts/apply-glue.cjs"`. Exits non-zero with a
// specific message when an expected transform is missing, so a regression in the pipe
// fails CI. The transformed native.d.ts is a build output consumed by `tsc`; the
// package's published types are the hand-maintained index.d.ts and are unaffected.
//
// This asserts the *presence of specific transforms*, not that the generated file matches
// a committed copy — a napi version bump would otherwise turn every release into a diff
// to review, which is the restated-inventory problem this check exists to avoid.

const fs = require('fs')

const NATIVE_DTS = 'native.d.ts'
const INDEX_JS = 'index.js'
const INDEX_DTS = 'index.d.ts'

const failures = []

function expectFile(file, what) {
  if (!fs.existsSync(file)) {
    failures.push(`${file} does not exist — was the native addon built? (${what})`)
    return null
  }
  return fs.readFileSync(file, 'utf8')
}

// --- Generated type declarations: the pipe's transform must have run -----------------
const dts = expectFile(NATIVE_DTS, 'generated by --dts native.d.ts')

if (dts !== null) {
  // Discriminated union replaces the flat interface napi emits by default.
  if (dts.includes('export type CellValue =')) {
    // present
  } else {
    failures.push(
      `${NATIVE_DTS} is missing the CellValue discriminated union ` +
        `("export type CellValue ="). The --pipe transform did not run.`
    )
  }

  if (dts.includes('export interface CellValue {')) {
    failures.push(
      `${NATIVE_DTS} still contains the flat "export interface CellValue {" — ` +
        `the union transform did not replace it.`
    )
  }

  if (dts.includes('export type CellValueInput =')) {
    // present
  } else {
    failures.push(
      `${NATIVE_DTS} is missing "export type CellValueInput =" — the --pipe transform did not run.`
    )
  }

  // Refined Cell setter: napi emits `set value(val: unknown)`, the pipe narrows it.
  if (dts.includes('set value(val: unknown)')) {
    failures.push(
      `${NATIVE_DTS} still types the Cell value setter as unknown — ` +
        `the class-body refinement did not run.`
    )
  }
  if (!dts.includes('set value(val: CellValueInput')) {
    failures.push(
      `${NATIVE_DTS} is missing the refined Cell value setter ` +
        `("set value(val: CellValueInput"). The --pipe transform did not run.`
    )
  }

  // getCell overload declarations, injected by the pipe into the napi-generated classes.
  for (const [label, needle] of [
    ['Worksheet.getCell(address: string)', 'getCell(address: string): Cell'],
    ['Worksheet.getCell(row, col)', 'getCell(row: number, col: number): Cell'],
    ['Row.getCell(col: number)', 'getCell(col: number): Cell'],
    ['Row.getCell(col: string)', 'getCell(col: string): Cell'],
    ['Worksheet.getColumn(col: number)', 'getColumn(col: number): Column'],
    ['Worksheet.getColumn(col: string)', 'getColumn(col: string): Column'],
  ]) {
    if (!dts.includes(needle)) {
      failures.push(`${NATIVE_DTS} is missing the ${label} overload declaration.`)
    }
  }
}

// --- Published entrypoint: hand-maintained, must still carry the runtime glue ---------
const indexJs = expectFile(INDEX_JS, 'checked-in package entrypoint')

if (indexJs !== null) {
  if (!indexJs.includes('__EXCELJS_GETCELL_GLUE__')) {
    failures.push(
      `${INDEX_JS} no longer carries the __EXCELJS_GETCELL_GLUE__ marker. ` +
        `This file is hand-maintained; the build does not regenerate it.`
    )
  }
  for (const [label, needle] of [
    ['Worksheet.prototype.getCell', 'nativeBinding.Worksheet.prototype.getCell'],
    ['Row.prototype.getCell', 'nativeBinding.Row.prototype.getCell'],
    ['Worksheet.prototype.getColumn', 'nativeBinding.Worksheet.prototype.getColumn'],
  ]) {
    if (!indexJs.includes(needle)) {
      failures.push(`${INDEX_JS} is missing the ${label} overload glue.`)
    }
  }
}

// --- Published vs generated declarations: they must agree --------------------------------
// The package publishes the hand-maintained index.d.ts while the build generates
// native.d.ts from the native surface. Nothing read both, so the two drifted silently:
// a runtime export with no type declaration, and enums declared `const` against a build
// configured not to emit them.
//
// Both files are parsed with the TypeScript compiler API rather than a keyword regex. A
// declaration in a .d.ts is exported WITHOUT the `export` keyword, so a keyword scan
// reports thirteen names as missing from index.d.ts that it actually exports.
//
// The name comparison is deliberately one-directional: the published file may carry
// aliases the generated one does not (WorksheetState mirrors ExcelJS), so only names the
// build generates are required to be declared. That keeps the check free of an allowlist.
// Returns the file's exported names, plus each declared enum mapped to whether it is
// declared `const`. Both facts come from the compiler API: the name set from the module
// symbol, the modifier from the declaration node. Only the modifier matters — member
// lists are the build's business, and a napi bump that reshuffles them is not a
// published-surface regression.
function parseDeclarations(file) {
  const ts = require('typescript')
  const program = ts.createProgram([file], {
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    skipLibCheck: true,
    noEmit: true,
  })
  const source = program.getSourceFile(file)
  if (source === undefined) {
    failures.push(`${file} could not be parsed by the TypeScript compiler API.`)
    return null
  }

  // A file with no top-level export is a script, not a module, and has no module symbol.
  // getExportsOfModule(undefined) throws a TypeError from inside the compiler, which would
  // discard every failure collected above and replace the report with a stack trace. An empty
  // or truncated build artifact is exactly the condition this script exists to diagnose, so it
  // has to degrade into a reported failure instead.
  const checker = program.getTypeChecker()
  const moduleSymbol = checker.getSymbolAtLocation(source)
  if (moduleSymbol === undefined) {
    failures.push(`${file} declares no exports, so it cannot be compared. Is the file empty or truncated?`)
    return null
  }

  const names = new Set(checker.getExportsOfModule(moduleSymbol).map((s) => s.name))

  const enums = new Map()
  const visit = (node) => {
    if (ts.isEnumDeclaration(node) && node.name !== undefined && ts.isIdentifier(node.name)) {
      const isConst = (ts.getCombinedModifierFlags(node) & ts.ModifierFlags.Const) !== 0
      enums.set(node.name.text, isConst)
    }
    ts.forEachChild(node, visit)
  }
  visit(source)

  return { names, enums }
}

const indexDts = expectFile(INDEX_DTS, 'published type declarations')
const generated = dts === null ? null : parseDeclarations(NATIVE_DTS)

if (indexDts !== null && generated !== null) {
  const published = parseDeclarations(INDEX_DTS)

  if (published !== null) {
    const missing = [...generated.names].filter((n) => !published.names.has(n))
    if (missing.length > 0) {
      failures.push(
        `${INDEX_DTS} does not declare ${missing.length} name(s) that ${NATIVE_DTS} ` +
          `declares: ${missing.join(', ')}. The build generates these from the native ` +
          `surface; a consumer cannot import a name the published types omit.`
      )
    }

    // Enum declaration form must match, or the published file misdescribes the enum.
    for (const [name, generatedIsConst] of generated.enums) {
      if (!published.enums.has(name)) continue // already reported by the coverage check
      const publishedIsConst = published.enums.get(name)
      if (publishedIsConst !== generatedIsConst) {
        failures.push(
          `${INDEX_DTS} declares enum ${name} as ` +
            `${publishedIsConst ? 'const enum' : 'enum'} but ${NATIVE_DTS} declares it as ` +
            `${generatedIsConst ? 'const enum' : 'enum'}. A const enum cannot be imported by ` +
            `a consumer compiling with isolatedModules; the published form must match the build.`
        )
      }
    }
  }
}

if (failures.length > 0) {
  console.error('[verify-build-output] FAILED\n')
  for (const f of failures) console.error(`  - ${f}`)
  console.error('')
  process.exit(1)
}

console.log(
  '[verify-build-output] OK — pipe transforms present, entrypoint glue intact, ' +
    'published declarations agree with the generated ones'
)
